                                                                                                                                                                                                              
  CREATE TABLE "CODE_DEVICE"                                                                                                                                                                       
   (	"DEVICE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 22 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"DEVICE_CODE" NVARCHAR2(64),                                                                                                                                                                                 
	"DEVICE_NAME" NVARCHAR2(255),                                                                                                                                                                                
	"FAB_ID" NUMBER(20,0),                                                                                                                                                                                       
	"MANAGEMENT_EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                        
	"CATEGORY_FIRST_CODE" NVARCHAR2(50),                                                                                                                                                                         
	"CATEGORY_SECOND_CODE" NVARCHAR2(50),                                                                                                                                                                        
	"LINE_ID" NUMBER(20,0),                                                                                                                                                                                      
	"AREA_ID" NUMBER(20,0),                                                                                                                                                                                      
	"IP" NVARCHAR2(64),                                                                                                                                                                                          
	"QRCODE_IMG" NVARCHAR2(255),                                                                                                                                                                                 
	"QRCODE_CONTENT" NVARCHAR2(255),                                                                                                                                                                             
	"REMARK" NVARCHAR2(255),                                                                                                                                                                                     
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                          
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                   
	"CREATION_DATE" DATE,                                                                                                                                                                                        
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                   
	"UPDATED_DATE" DATE,                                                                                                                                                                                         
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                           
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                            
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                
	 PRIMARY KEY ("DEVICE_ID")                                                                                                                                                                                   
  USING INDEX  ENABLE                                                                                                                                                                                         
   ) ;                                                                                                                                                                                                        

